using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly EvaluationResponse _evaluationMetrics;
    private readonly string[] _categoryNames;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        IDataView dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.3);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        // Extract ordered category names from the label key column
        var schema = _model.GetOutputSchema(split.TrainSet.Schema);
        var labelCol = schema["Label"];
        var keyType = labelCol.Type as KeyDataViewType;
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        labelCol.GetKeyValues(ref keyValues);
        _categoryNames = keyValues.DenseValues()
            .Select(v => v.ToString())
            .ToArray();

        _evaluationMetrics = Evaluate(split.TestSet);

        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _categoryNames.Length; i++)
        {
            confidence[_categoryNames[i]] = i < prediction.Score.Length
                ? prediction.Score[i]
                : 0f;
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;

    private EvaluationResponse Evaluate(IDataView testData)
    {
        var predictions = _model.Transform(testData);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        var perCategory = new List<CategoryMetric>();
        for (int i = 0; i < metrics.PerClassLogLoss.Count && i < _categoryNames.Length; i++)
        {
            var confusionMatrix = metrics.ConfusionMatrix;
            var counts = confusionMatrix.Counts;
            int classCount = counts.Count;

            double tp = i < classCount && i < counts[i].Count ? counts[i][i] : 0;
            double colSum = 0;
            double rowSum = i < classCount ? counts[i].Sum() : 0;
            for (int r = 0; r < classCount; r++)
            {
                if (i < counts[r].Count) colSum += counts[r][i];
            }

            double precision = colSum > 0 ? tp / colSum : 0;
            double recall = rowSum > 0 ? tp / rowSum : 0;
            double f1 = precision + recall > 0
                ? 2 * precision * recall / (precision + recall) : 0;

            perCategory.Add(new CategoryMetric
            {
                Category = _categoryNames[i],
                Precision = Math.Round(precision, 4),
                Recall = Math.Round(recall, 4),
                F1Score = Math.Round(f1, 4)
            });
        }

        return new EvaluationResponse
        {
            MicroAccuracy = (float)Math.Round(metrics.MicroAccuracy, 4),
            MacroAccuracy = (float)Math.Round(metrics.MacroAccuracy, 4),
            LogLoss = (float)Math.Round(metrics.LogLoss, 4),
            LogLossReduction = (float)Math.Round(metrics.LogLossReduction, 4),
            PerCategory = perCategory
        };
    }
}

